\if :{?iqror_chain}
\else
\set ON_ERROR_STOP on
do $iqror_guard$ begin raise exception 'iqror: fin-version.sql ALOHIDA ishga tushirilmaydi — zanjirdagi keyingi fayllar uni qayta belgilaydi (alohida ishlatilsa xavfsizlik/moliya qoidalari ESKI holatga qaytadi)' using hint = 'Butun zanjir: bash ~/iqror-repo/deploy.sh  (eski deploy.sh bo''lsa avval: cd ~/iqror-repo && git fetch origin claude/iqror-med-school-impl-iqdntl && git checkout FETCH_HEAD -- deploy.sh migration && bash deploy.sh). Qo''lda: bash ~/iqror-repo/migration/chain.sh | sudo docker exec -i supabase-db psql -U postgres -d postgres -q'; end $iqror_guard$;
\quit
\endif
-- =====================================================================
-- fin-version.sql — MOLIYA ISH REJASI, 1a-BOSQICH (F1.18): MODUL RELIZI BELGISI (deploy markeri).
--   app.kassa_version() — bazaga o'rnatilgan «Kassa» / moliya moduli relizining tartib raqami. Zanjir bitta tranzaksiyada
--   qo'llangani uchun bu funksiya BOR bo'lsa — modulning barcha fayllari (fin-core … fin-period) ham qo'llangan.
--   Kim o'qiydi:
--     • kassa_state() javobidagi "version" — sahifa (assets/js/fin-kassa.js: SERVER_VER) o'zi kutgan reliz bilan solishtiradi:
--       farq bo'lsa «sahifani yangilang» yoki «server yangilanmagan» ogohlantirishi;
--     • migration/kassa-checks.sql (o'rnatishdan keyingi, faqat o'qiydigan tekshiruv) va migration/deploy/full-deploy.sh.
--   QOIDA: moliya modulining server shartnomasi o'zgarganda (yangi / o'zgargan RPC, jadval, javob tuzilishi) raqam BIRGA
--     oshiriladi: shu fayl, fin-kassa.js (SERVER_VER) va kassa-checks.sql (want_ver va kutilgan sonlar) — uchalasi bir xil.
--     So'ng kassa-checks.sql dagi himoya mantig'i barmoq izlari (23-band) toza zanjirdan qayta yoziladi: bash migration/kassa-fingerprints.sh
--     (lokal; himoya funksiyasi, trigger, o'qish siyosati yoki cheklov o'zgargan har o'zgarishda ham — aks holda test-kassa-checks.sql
--     toza holati va deploydagi «Kassa tekshiruvi» farqni ko'rsatadi).
--   Bu fayl zanjirda moliya fayllarining OXIRGISI bo'lib qoladi (yangi moliya migratsiyalari undan OLDIN qo'shiladi).
--   Relizlar: 1 — 1a-bosqich (2026-11-10); 2 — avans hisoboti (nc_adv_report), hisobotsiz yangi avans qoidasi (2026-11-12);
--     3 — onlayn kassa Z-hisoboti (kassa_day_z, kun javobida «z», nazoratda «zreport») (2026-11-12);
--     4 — yuridik shaxsga kassadan naqd to'lov: Direktor tasdig'i (sozlama orgCashMax), javobda «orgCash», nazoratda «orgCash30»;
--     5 — KO-3 kassa orderlari jurnali (kassa_journal; chop etish va XLSX — sahifada);
--     6 — KO-3 Excel eksporti FD-28 bo'yicha (kassa_journal_export: kassirga yo'q, 2-ro'yxatga ismsiz);
--     7 — RP-08 oylik statiya matritsasi (kassa_matrix) va buxgalter uchun oylik kassa to'plami (kassa_month_pack);
--     8 — eslatmalar: muddati o'tgan avans (holat va Telegram nazoratida «accOverdue»), RP-22 haftalik KPI (kassa_kpi; Telegram «week»);
--     9 — dalolatnomalar raqami hujjat turi seriyasida (cash_docs.series: ACT «Д-», OFS «ЎҲ-», ADV «А-»; noyoblik va bo'shliq — seriya bo'yicha);
--     10 — F1.21 buxgalter roli: o'qish ro'yxati — fin-rights.sql («*_acc_sel» siyosatlari; invoices_acc, payments_acc, refunds_acc,
--          salary_payments_acc, payroll_lines_acc ko'rinishlari), nurse-sick.sql (students_billing), parent-link-canon.sql (claim_child
--          buxgalter hisobini rad etadi); reports-roles.sql — buxgalterga qo'shimcha lavozim berilmaydi; kassa javoblari va hujjat
--          suratlarida xodim emaili yo'q (kassa_names, kassa_refs, kassa_shortage_decide, kassa_refund_request; ism o'rnida email
--          turgan eski hisoblar ham — bog'langan xodim kartasi ismi yoki uid); kassa_state «accRead» — sahifadagi buxgalter bo'limlari kaliti (app.acc_read()).
--     11 — mustaqil ko'rik tuzatishlari (g1–g10): «Xodim qaytargan pul» (in_staff_return) — oy majburiy, avans / maosh yozuviga tushadi;
--          «Kamomadni qoplash (xodim)» (in_damage_repay); ishga tushirish chegarasi, to'xtatish va qayta ishga tushirish (kassa:live_day,
--          paused_live_day, rollback_pending, restart_recount, restart_gap); vazifalar ajratilishi (kassa:self_party / self_report /
--          self_pay / self_verify, fin_counterparty_confirm, kassa_doc_pay — ok=false, kassa:org_director); kun egasi va ikki bosqichli
--          smena topshirish (cash_handovers, kassa_handover_accept / kassa_handover_cancel); kunni yopish va smena topshirish — expected va
--          pendingRefs (pendingSum / pendingCount rad), «Қ» blankalari (paper), kassa:stale; so'rov izi (reqHash, kassa:ref_mismatch),
--          kassa_pay_guard, yopilgan davrda tushum qulfi; ketgan xodim (kassa:emp_left), printsOrig, kassa_state.me.name;
--          kassa-checks.sql — 23-band (himoya mantig'i barmoq izi) va 24-band (vazifalar ajratilishi ma'lumoti).
--     12 — yakuniy ko'rik tuzatishlari (g11): kassani qayta to'xtatish (tayyorlangan qayta ishga tushirish) to'xtatish qulfi va shartlari
--          bilan, to'xtatilgan kassada ochiq kun — blockReason 'paused'; fiskal chek takrori o'tkazishda kassa qulfi ostida (kassa:fiscal_dup);
--          so'rovni yolg'iz tasdiqlagan xodim pulini bermaydi (kassa:self_pay), Direktor o'ziga pulni / naqd maoshni o'zi bermaydi
--          (kassa:self_recipient, FD-48); kunni qayta ochilishidan oldin yopgan xodim tekshirmaydi; qaytarish oynasi kaliti — naqd so'rov va
--          naqdsiz qaytarish bir-birini rad etadi (kassa:ref_mismatch; refund_invoice — ref_mismatch, so'rov posbonda saqlanadi); sinov
--          kassasida navbat yozuvlari rad (kassa:pending_test); 24-band — ikki yangi qator.
--     13 — 2-bosqich F2.1: «Buxgalteriya» xarajatlari reyestri (fin-exp.sql) — fin_exp_docs jadvali, fin_exp_refs / fin_exp_save /
--          fin_exp_void (statiya qatorlari, kontragent, hujjat №, ilova, server muallif; tuzatish — replaces, bekor qilish — sabab bilan;
--          takror: clientRef, fin:exp_dup); expenses."expDocId"; trg_fin_exp_guard (hujjat qatori to'g'ridan-to'g'ri o'zgarmaydi),
--          trg_fin_exp_doc_guard (hujjat — faqat bekor qilinadi); app.kassa_exp_category — OP-12 / OP-13 «Soliq».
--     14 — 2-bosqich F2.2: kontragent kartasi to'liq (fin-core.sql ustunlari: hisob raqami, MFO, bank nomi, shartnoma №, sanasi va
--          muddati, rev, updatedAt / updatedBy; cheklovlar fin_counterparties_bank_chk / _contract_chk; STIR — 9 raqam,
--          app.fin_cp_stir_check) va fin-cp.sql: fin_cp_save (karta, versiya bilan; fin:cp_dup, fin:cp_stir_dup, fin:cp_changed),
--          fin_cp_statement (RP-10 kontragent ko'chirmasi; faylda FD-28 bo'yicha ismsiz).
--     15 — 2-bosqich F2.13: qayta tasnif dalolatnomasi («ҚТ-», seriya 'FIX'; Sh-8 B11): kassa.sql — cash_doc_fixes (holat, before /
--          after, raqam tasdiqda; bitta kutilayotgan so'rov), trg_kassa_fix_guard, app.kassa_eff_art / app.kassa_eff_doc (amaldagi holat);
--          kassa-fix.sql — kassa_fix_request (2-ro'yxat), kassa_fix_decide (Direktor; «Buxgalteriya» qatori yangilanadi),
--          kassa_fix_cancel, kassa_fix_list, kassa_fix_get; kassa_doc_json — fixes / eff; kassa_matrix va fin_cp_statement — amaldagi
--          statiya va tomon; kassa_checks — fixPending / fixes30; kassa_state — pending.fixToApprove.
--     16 — buxgalter savollari (Sh-8) bo'yicha egasi qarorlari (2026-11-26): B15 — bankka topshirish (inkassatsiya) jadvali: fin_org_set
--          depositDays / depositKeep (fin_org.extra; kalit yo'q — juma), kassa-day.sql app.kassa_deposit_cfg, app.kassa_limit_hint (kassa
--          limiti tavsiyasi — bankka ariza uchun), kassa_state.deposit (topshirish kuni eslatmasi), kassa_checks.deposit / depositMissed30;
--          B19 / B20 — kassa_month_pack: offsets (E5 o'zaro hisob — JShDS imtiyozi), staffDiscounts (E6 xodim farzandi chegirmasi),
--          payroll (E7 vedomost va to'lovlar — ish haqi fondi bilan solishtirish); FD-28 bo'yicha 2-ro'yxatga ismsiz.
--     17 — 2-bosqich F2.14 va F2.15 (Sh-8 B17, B1): kassa_pay_sheet — xodimning o'quv yili ish haqi to'lov qaydnomasi (shu xodimning
--          naqd maosh, avans va qaytim orderlari; boshqa xodimlar summalarisiz; kassagacha naqd yozuvlar — ma'lumot); kassa_month_pack —
--          postings (E8 provodkalar, 1C ga yuklash uchun: hujjatlar asl holatda, qayta tasnif — alohida tuzatish yozuvi).
--     18 — 2-bosqich F2.8 (1-qism): komissiya inventarizatsiyasi (INV-16) — kassa_day_close inv (oylik / yillik sanash, komissiya majburiy,
--          qat'iy hisobdagi blankalar: app.kassa_blanks), kassa_handover mol (moddiy javobgar shaxs almashganda), cash_counts /
--          cash_handovers "molChange" va blanks, kassa_day_json.invKind; kassa_month_check — oy oxiri ro'yxati; kassa_checks.invMissing.
--     19 — 2-bosqich F2.8 (2-qism): davr qulfi barcha pul jadvallariga (fin-period.sql): hisob-fakturalar (app.fin_lock_invoices —
--          hisoblanish kuni oyning 1-kuni: yangi faktura, o'chirish, summa / chegirma / imtiyoz / kasallik / oy / o'quvchi / oraliq,
--          bekor qilish; to'lov qo'llanishi — yo'q), avans harakatlari (app.fin_lock_credit — "at" server vaqti, yopilgan davr yozuvi
--          o'zgarmaydi), qaytarishlar (app.fin_lock_refunds — pul maydonlari), oylik vedomost (app.fin_lock_payroll — hisoblanish kuni
--          oyning oxirgi kuni); app.fin_lock_hit; triggerlar trg_fin_zlock (invoices, credit_ledger, refunds, payroll_runs, payroll_lines);
--          kassa_month_check — tasdiqlanmagan vedomost ogohlantirishi (payroll.approvalFrom).
--     20 — 2-bosqich F2.4 va F2.11: expenses.kind ('accrual' — oylik maoshni hisoblash qatori «payroll__YYYY-MM», 'expense' — qolgani;
--          faqat id dan — trigger trg_fin_exp_0kind / app.fin_exp_kind, mijoz qiymati e'tiborsiz), expenses_accrual_chk (hisoblash qatorida
--          usul va hujjat yo'q); naqd ko'rinishlar — kind bo'yicha (kassa_cash_guard, kassa_cash_rows, kassa_reconcile_range P4,
--          fin_exp_legacy_check); fin_refund_credit — o'quvchi avansini naqdsiz (bank / karta) qaytarish (Direktor; idempotent;
--          kutilayotgan naqd so'rovlar bilan), refunds.payee; kassa_refund_request — shu oyna kaliti bilan naqdsiz qaytarish bo'lsa rad.
--     21 — 2-bosqich F2.12: patta tekshiruv kaliti — cash_doc_verify (KO-1 raqam olganda, trigger trg_kassa_vtok / app.kassa_vtok; eski
--          kirim orderlariga zanjirda), app.kassa_doc_json → vtok, public.verify_patta (mehmon ham; ismsiz: holat, raqam, sana, summa,
--          tashkilot); public.kassa_book_cover — kassa kitobi yil muqovasi va varaqlar guvohnomasi (KO-4 varaqlari, uzilish, ochiq kun).
--     22 — 2-bosqich F2.7: faktura tarkibi — invoices."grossAmount" / "discountParts" (asosiy zanjir: discounts.sql, inv-parts.sql —
--          trigger trg_invoice_zparts, eski fakturalarni to'ldirish; reprice_invoice meta); shu modulda — davr qulfi tarkib ustunlarini
--          ham qamraydi (app.fin_lock_invoices), buxgalter ko'rinishi invoices_acc da tarkib ustunlari.
--     23 — 2-bosqich F2.5: RP-09 — barcha to'lov usullari bo'yicha statiya matritsasi (o'quv / kalendar yili; fin-matrix.sql:
--          public.fin_matrix — Direktor, Moliya menejeri, buxgalter) va maosh taqsimoti (tasdiqlangan vedomost × lavozim ->
--          EX-01…EX-04, app.fin_pos_article); nazorat — har manba bo'yicha hujjatlar soni va jami (Jami = Σ hujjatlar).
--     24 — 2-bosqich F2.6 (1-qism): avans hisoboti ikki bosqichda (kassa_adv_report — tasdiq kutadi; kassa_doc_approve ->
--          app.kassa_adv_approve: boshqa 2-ro'yxat xodimi / Direktor, kirituvchi va hisobdor emas, qoldiq o'zgarmagan — kassa:adv_stale;
--          bitta kutilayotgan hisobot — kassa:adv_pending); ortiqcha sarf — Kt 6970 qatorlari (app.kassa_acc_part — 4230 qismi,
--          app.kassa_acc_due — hisobdorga qarzimiz); «Ortiqcha sarfni qoplash» KO-2 (out_overspend, Dt 6970 Kt 5010, qarzdan oshmaydi);
--          hisobdorga avans maqsadi (purposeArticle — sourceSnapshot); RP-07 public.kassa_acc_card (app.kassa_acc_fifo); kassa_checks.accDue;
--          kassa_staff_open.due.
--     25 — 2-bosqich F2.6 (2-qism): avans hisoboti cheklari surati — yopiq «receipts» bucket (2-ro'yxat va Direktor), public.cash_doc_files
--          (faqat qo'shiladi), kassa_adv_report.files, public.kassa_doc_files / kassa_doc_files_add (app.kassa_files_norm, kassa_files_add),
--          kassa_doc_json.filesN; avans hisoboti muddati sozlamasi (fin_org.extra.advDays, standart 3 ish kuni — app.kassa_adv_days) va
--          muddati o'tgan avansi bor xodimga yangi avansni bloklash (extra.advBlock — app.kassa_adv_block, app.kassa_acc_late: so'rov va pul
--          berishda kassa:adv_overdue); kassa_acc_card.advDays.
--     26 — 2-bosqich F2.9 «Huquqlar II» (fin-guard.sql, zanjir oxirida): pul jadvallariga to'g'ridan-to'g'ri yozuv detektori
--          (public.fin_direct_log, trg_fin_direct — app.fin_direct_detect / app.fin_direct_note) va qulfi (fin_org.extra.directGuard — «7 kun
--          0 yozuv» sharti: app.fin_guard_check, fin_org_set; guardSince), barcha pul funksiyalariga «SET iqror.fin_rpc = '1'» bayrog'i;
--          public.fin_pay_cancel («🚫 Bekor»), public.fin_pay_rev_done («✓ Bajarildi»), public.fin_guard_report, kassa_checks.direct
--          (app.fin_guard_brief), public.fin_marketing_spend (RF-12; exp_sel — marketingsiz); RF-11 g'aznachi = kassa operatori
--          (app.is_finance / app.is_cashier); credit_ledger cl_ins — faqat Direktor; fin_org.extra o'zgarishlar tarixida.
--   HOLAT: run-all.sql'da «--dev \ir» — prod'ga hali chiqmaydi.
-- =====================================================================
create or replace function app.kassa_version() returns int
language sql immutable set search_path = public, app, pg_temp as $$ select 26 $$;
revoke all on function app.kassa_version() from public, anon, authenticated;
